<template>
  <div class="app-container agent-page">
    <div class="page-heading"><div><h2>工作流模板</h2><p>管理版本化 DAG、角色白名单和预算边界。</p></div><el-button type="primary" @click="openCreate">创建新版本</el-button></div>
    <el-card shadow="never">
      <el-form :inline="true" class="toolbar"><el-form-item><el-input v-model="query.keyword" placeholder="工作流 key 或名称" clearable style="width: 240px" @keyup.enter="load" /></el-form-item><el-form-item><el-select v-model="query.taskType" placeholder="任务类型" clearable style="width: 160px" @change="load"><el-option v-for="item in taskTypes" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item><el-select v-model="query.enabled" placeholder="全部状态" clearable style="width: 140px" @change="load"><el-option label="已启用" :value="true" /><el-option label="已停用" :value="false" /></el-select></el-form-item><el-button type="primary" :loading="loading" @click="load">查询</el-button></el-form>
      <el-table v-loading="loading" :data="rows" empty-text="暂无工作流模板"><el-table-column prop="workflowKey" label="工作流 Key" min-width="180" /><el-table-column prop="displayName" label="名称" min-width="170" /><el-table-column prop="version" label="版本" width="80" /><el-table-column prop="taskType" label="任务类型" width="160" /><el-table-column prop="maxSteps" label="最大步骤" width="100" /><el-table-column prop="failurePolicy" label="失败策略" width="160" /><el-table-column label="状态" width="90"><template #default="{ row }"><el-tag :type="row.enabled ? 'success' : 'info'">{{ row.enabled ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openDetail(row)">详情</el-button><el-button v-if="!row.enabled" link type="warning" @click="activate(row)">启用</el-button></template></el-table-column></el-table>
      <pagination v-show="total > 0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load" />
    </el-card>
    <el-drawer v-model="detailVisible" title="工作流详情" size="760px" destroy-on-close><template v-if="selected.workflowKey"><el-descriptions :column="2" border><el-descriptions-item label="工作流 Key">{{ selected.workflowKey }}</el-descriptions-item><el-descriptions-item label="版本">{{ selected.version }}</el-descriptions-item><el-descriptions-item label="任务类型">{{ selected.taskType }}</el-descriptions-item><el-descriptions-item label="失败策略">{{ selected.failurePolicy }}</el-descriptions-item><el-descriptions-item label="最大步骤">{{ selected.maxSteps }}</el-descriptions-item><el-descriptions-item label="最大运行时间">{{ selected.maxRuntimeSeconds }} 秒</el-descriptions-item><el-descriptions-item label="审批">{{ selected.approvalRequired ? '需要' : '不需要' }}</el-descriptions-item><el-descriptions-item label="状态">{{ selected.enabled ? '启用' : '停用' }}</el-descriptions-item></el-descriptions><div class="schema-heading">角色白名单</div><pre class="schema-content">{{ formatJson(selected.allowedRolesJson) }}</pre><div class="schema-heading">工具白名单</div><pre class="schema-content">{{ formatJson(selected.allowedToolsJson) }}</pre><div class="schema-heading">DAG 步骤</div><pre class="schema-content">{{ formatJson(selected.stepsJson) }}</pre></template></el-drawer>
    <el-dialog v-model="createVisible" title="创建工作流版本" width="760px" destroy-on-close><el-form ref="formRef" :model="form" :rules="rules" label-width="135px"><el-form-item label="工作流 Key" prop="workflowKey"><el-input v-model="form.workflowKey" placeholder="例如 operations_review" /></el-form-item><el-form-item label="显示名称" prop="displayName"><el-input v-model="form.displayName" /></el-form-item><el-form-item label="任务类型" prop="taskType"><el-select v-model="form.taskType"><el-option v-for="item in taskTypes" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item label="DAG 步骤 JSON" prop="stepsJson"><el-input v-model="form.stepsJson" type="textarea" :rows="7" /></el-form-item><el-form-item label="角色白名单" prop="allowedRolesJson"><el-input v-model="form.allowedRolesJson" type="textarea" :rows="2" /></el-form-item><el-form-item label="工具白名单" prop="allowedToolsJson"><el-input v-model="form.allowedToolsJson" type="textarea" :rows="2" /></el-form-item><el-form-item label="失败策略"><el-select v-model="form.failurePolicy"><el-option v-for="item in failurePolicies" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item label="最大步骤"><el-input-number v-model="form.maxSteps" :min="1" :max="32" /></el-form-item><el-form-item label="需要审批"><el-switch v-model="form.approvalRequired" /></el-form-item></el-form><template #footer><el-button @click="createVisible = false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">创建停用版本</el-button></template></el-dialog>
  </div>
</template>

<script setup name="JgAgentWorkflow">
import { activateAgentWorkflow, createAgentWorkflow, getAgentWorkflow, listAgentWorkflows } from '@/api/jiugai/agentConfig'
import { ElMessageBox } from 'element-plus'
const loading = ref(false); const saving = ref(false); const rows = ref([]); const total = ref(0); const detailVisible = ref(false); const createVisible = ref(false); const selected = ref({}); const formRef = ref()
const taskTypes = ['CONTENT_CREATION', 'GENERAL', 'OPERATIONS_REVIEW']; const failurePolicies = ['STOP', 'CONTINUE_DEGRADED', 'RETRY']; const query = reactive({ pageNum: 1, pageSize: 20, keyword: '', enabled: undefined, taskType: undefined })
const form = reactive({ workflowKey: '', displayName: '', taskType: 'GENERAL', stepsJson: '[]', allowedRolesJson: '[]', allowedToolsJson: '[]', maxSteps: 12, maxRuntimeSeconds: 1800, maxTokens: 20000, maxCost: 0, failurePolicy: 'STOP', approvalRequired: true }); const rules = { workflowKey: [{ required: true, message: '请输入工作流 Key', trigger: 'blur' }], displayName: [{ required: true, message: '请输入显示名称', trigger: 'blur' }], taskType: [{ required: true, message: '请选择任务类型', trigger: 'change' }], stepsJson: [{ required: true, message: '请输入步骤 JSON', trigger: 'blur' }], allowedRolesJson: [{ required: true, message: '请输入角色白名单', trigger: 'blur' }], allowedToolsJson: [{ required: true, message: '请输入工具白名单', trigger: 'blur' }] }
function formatJson(value) { if (!value) return '-'; try { return JSON.stringify(JSON.parse(value), null, 2) } catch { return String(value) } }
async function load() { loading.value = true; try { const response = await listAgentWorkflows(query); rows.value = response.rows || []; total.value = response.total || 0 } finally { loading.value = false } }
async function openDetail(row) { const response = await getAgentWorkflow(row.id); selected.value = response.data || row; detailVisible.value = true }
function openCreate() { Object.assign(form, { workflowKey: '', displayName: '', taskType: 'GENERAL', stepsJson: '[]', allowedRolesJson: '[]', allowedToolsJson: '[]', maxSteps: 12, maxRuntimeSeconds: 1800, maxTokens: 20000, maxCost: 0, failurePolicy: 'STOP', approvalRequired: true }); createVisible.value = true }
async function submit() { await formRef.value.validate(); saving.value = true; try { await createAgentWorkflow({ ...form }); createVisible.value = false; await load() } finally { saving.value = false } }
async function activate(row) { await ElMessageBox.confirm(`确认启用 ${row.workflowKey} v${row.version}？同 key 的其他版本会停用。`, '版本切换', { type: 'warning' }); await activateAgentWorkflow(row.id); await load() }
onMounted(load)
</script>
<style scoped>
.agent-page { color: #1f2937; }.page-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 18px; }.page-heading h2 { margin: 0 0 6px; font-size: 22px; }.page-heading p { margin: 0; color: #6b7280; }.toolbar { margin-bottom: 6px; }.schema-heading { margin: 22px 0 8px; color: #606266; font-weight: 600; }.schema-content { max-height: 280px; margin: 0; padding: 12px; overflow: auto; color: #303133; background: #f5f7fa; border: 1px solid #ebeef5; border-radius: 4px; white-space: pre-wrap; word-break: break-word; }
</style>
